// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    Recorder recorder;

    function setUp() public {
        c = new Reentrance();
        recorder = new Recorder();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0 && amount <= address(this).balance + 1e30);
        vm.deal(address(recorder), amount);

        vm.prank(address(recorder));
        c.addToBalance{value: amount}();

        uint256 before = recorder.totalReceived();
        vm.prank(address(recorder));
        c.withdrawBalance();

        assertTrue(recorder.totalReceived() - before == amount);
    }
}

contract Recorder {
    uint256 public totalReceived;
    receive() external payable {
        totalReceived += msg.value;
    }
}
